// ---------- Sticky header stack: topbar fixed, tabbar sticks right under it ----------
const topbarEl = document.querySelector('.topbar');
const tabbarEl = document.querySelector('.tabbar');
function syncStickyOffsets(){
  const h = topbarEl.offsetHeight;
  tabbarEl.style.top = h + 'px';
}
window.addEventListener('load', syncStickyOffsets);
window.addEventListener('resize', syncStickyOffsets);
syncStickyOffsets();

// ---------- Tabbar turns white the moment the active panel's cover image top edge reaches its bottom edge ----------
function checkCoverOverlap(){
  const tabbarBottom = tabbarEl.getBoundingClientRect().bottom;
  const covers = document.querySelectorAll('.hero');
  let overlapping = false;
  covers.forEach(c=>{
    const r = c.getBoundingClientRect();
    if(r.height > 0 && r.top <= tabbarBottom && r.bottom >= tabbarBottom){ overlapping = true; }
  });
  tabbarEl.classList.toggle('over-cover', overlapping);
}
window.addEventListener('scroll', checkCoverOverlap, {passive:true});
window.addEventListener('resize', checkCoverOverlap);
checkCoverOverlap();

