// ---------- Cover image parallax (per-image, based on its own viewport position) ----------
const parallaxImgs = Array.from(document.querySelectorAll('.hero-photo'));
const PARALLAX_SCALE = 1.35;
function updateParallax(){
  parallaxImgs.forEach(img=>{
    const parent = img.parentElement;
    const rect = parent.getBoundingClientRect();
    const buffer = rect.height * (PARALLAX_SCALE - 1) / 2;
    let offset = rect.top * 0.15;
    if(offset > buffer) offset = buffer;
    if(offset < -buffer) offset = -buffer;
    img.style.transform = `translateY(${offset}px) scale(${PARALLAX_SCALE})`;
  });
}
window.addEventListener('scroll', updateParallax, {passive:true});
window.addEventListener('resize', updateParallax);
updateParallax();

