// ---------- Word counters ----------
function wireCounter(taId,countId,limit){
  const ta=document.getElementById(taId), cd=document.getElementById(countId);
  ta.addEventListener('input',()=>{
    const words=ta.value.trim()===''?0:ta.value.trim().split(/\s+/).length;
    cd.textContent=words+' / '+limit+' words';
    cd.classList.toggle('over',words>limit);
  });
}
wireCounter('visionText','visionCount',300);
wireCounter('descText','descCount',300);

