// ---------- Front label field list (priority reordering: changing one row's
// number moves it there and shifts the others, always a clean 1..N permutation) ----------
const fields=[
  {label:'Brand Logo', isLogo:true},
  {label:'Producer / Estate Name',ph:'E.g. Château Lafite Rothschild, Pheasant\u2019s Tears, etc.'},
  {label:'Wine Name / Cuvée',ph:'E.g. Carruades de Lafite, Kisi Premium, etc.'},
  {label:'Appellation / PDO / AVA',ph:'E.g. Pauillac AOC, Kakheti PDO, Napa Valley AVA, etc.'},
  {label:'Classification',ph:'E.g. Premier Grand Cru Classé, Gran Reserva, Grand Cru, etc.'},
  {label:'Grape Variety',ph:'E.g. Chardonnay, Saperavi, Kisi, etc. If multiple, separate with commas.'},
  {label:'Region',ph:'E.g. Bordeaux, Kakheti, Barossa Valley, etc.'},
  {label:'Special Designation',ph:'E.g. Vieilles Vignes, Qvevri, Estate Grown, Single Vineyard, etc.'},
  {label:'Vintage',ph:'E.g. 2020, 2023, etc.'},
  {label:'Country',ph:'E.g. France, Georgia, Australia, etc.'},
  {label:'Alcohol / Bottle Volume', isPair:true},
];
const fieldList=document.getElementById('fieldList');
let fieldOrder=fields.map((_,i)=>i);
function renderFieldRows(){
  fieldList.innerHTML='';

  const totalRows = fieldOrder.length;
  const MIN_H=30, MIN_LABEL_FONT=10.5, MIN_CTRL_FONT=10.5;
  const MAX_H=MIN_H*3, MAX_LABEL_FONT=15, MAX_CTRL_FONT=MIN_CTRL_FONT*3;
  function scaleFor(index){
    const t = index/(totalRows-1);
    return {
      h: Math.round(MAX_H - t*(MAX_H-MIN_H)),
      labelFont: (MAX_LABEL_FONT - t*(MAX_LABEL_FONT-MIN_LABEL_FONT)).toFixed(1),
      ctrlFont: (MAX_CTRL_FONT - t*(MAX_CTRL_FONT-MIN_CTRL_FONT)).toFixed(1)
    };
  }

  fieldOrder.forEach((origIdx,pos)=>{
    const f=fields[origIdx];
    const s=scaleFor(pos);
    const options=fieldOrder.map((_,n)=>`<option value="${n+1}" ${n===pos?'selected':''}>${n+1}</option>`).join('');
    if(f.isLogo){
      const row=document.createElement('div');
      row.className='field-row';
      row.innerHTML=`
        <label class="field-row-label" style="font-size:${s.labelFont}px;">${pos===0?'Priority':''}</label>
        <label class="field-row-label" style="font-size:${s.labelFont}px;">${f.label}<span class="info-inline" data-tip="Lorem ipsum dolor sit amet — a short tip about this section will appear here.">?</span></label>
        <select data-orig="${origIdx}" style="height:${s.h}px;font-size:${s.ctrlFont}px;">${options}</select>
        <button class="upload-btn-wide" type="button" style="height:${s.h}px;font-size:${s.ctrlFont}px;">
          <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" width="16" height="16"><path d="M12 3v12M7 8l5-5 5 5M5 21h14"/></svg>
          Upload Logo
        </button>`;
      fieldList.appendChild(row);
    } else if(f.isPair){
      const row=document.createElement('div');
      row.className='field-row-pair';
      row.innerHTML=`
        <select data-orig="${origIdx}" class="field-row-pair-num-select" style="height:${s.h}px;font-size:${s.ctrlFont}px;">${options}</select>
        <div class="field-row-pair-col">
          <label class="field-row-label" style="font-size:${s.labelFont}px;">Alcohol</label>
          <input type="text" placeholder="E.g. 12.5%" style="height:${s.h}px;font-size:${s.ctrlFont}px;">
        </div>
        <div class="field-row-pair-col">
          <label class="field-row-label" style="font-size:${s.labelFont}px;">Bottle Volume</label>
          <input type="text" placeholder="E.g. 750ml, 1L, etc." style="height:${s.h}px;font-size:${s.ctrlFont}px;">
        </div>`;
      fieldList.appendChild(row);
    } else {
      const row=document.createElement('div');
      row.className='field-row';
      row.innerHTML=`
        <label class="field-row-label" style="font-size:${s.labelFont}px;">${pos===0?'Priority':''}</label>
        <label class="field-row-label" style="font-size:${s.labelFont}px;">${f.label}</label>
        <select data-orig="${origIdx}" style="height:${s.h}px;font-size:${s.ctrlFont}px;">${options}</select>
        <input type="text" placeholder="${f.ph}" style="height:${s.h}px;font-size:${s.ctrlFont}px;">`;
      fieldList.appendChild(row);
    }
  });
  fieldList.querySelectorAll('select[data-orig]').forEach(sel=>{
    sel.addEventListener('change',()=>{
      const origIdx=parseInt(sel.dataset.orig,10);
      const newPos=parseInt(sel.value,10)-1;
      const oldPos=fieldOrder.indexOf(origIdx);
      fieldOrder.splice(oldPos,1);
      fieldOrder.splice(newPos,0,origIdx);
      renderFieldRows();
    });
  });
}
renderFieldRows();

