// ---------- Orientation & size diagram ----------
const widthMM=document.getElementById('widthMM'), heightMM=document.getElementById('heightMM');
const diagramRect=document.getElementById('diagramRect'), dimTop=document.getElementById('dimTop'), dimSide=document.getElementById('dimSide');
function updateDiagram(){
  const w=parseFloat(widthMM.value)||110, h=parseFloat(heightMM.value)||80;
  const scale=3.3;
  diagramRect.style.width=Math.max(120,w*scale)+'px';
  diagramRect.style.height=Math.max(100,h*scale)+'px';
  dimTop.textContent=w+'mm';
  dimSide.textContent=h+'mm';
}
widthMM.addEventListener('input',updateDiagram);
heightMM.addEventListener('input',updateDiagram);
document.querySelectorAll('input[name=orientation]').forEach(r=>{
  r.addEventListener('change',()=>{
    if(r.value==='v' && r.checked){ [widthMM.value,heightMM.value]=[heightMM.value,widthMM.value]; }
    if(r.value==='h' && r.checked){ if(parseFloat(widthMM.value)<parseFloat(heightMM.value)) [widthMM.value,heightMM.value]=[heightMM.value,widthMM.value]; }
    updateDiagram();
  });
});
updateDiagram();

