// ---------- Subtotal computation ----------
function recompute(panelId,outId){
  const panel=document.getElementById(panelId);
  let sum=0;
  panel.querySelectorAll('.price-row input[type=checkbox][data-price]').forEach(cb=>{
    if(cb.checked) sum+=parseInt(cb.dataset.price,10);
  });
  document.getElementById(outId).textContent=sum;
}
function syncCheckboxPair(idA, idB, panelId, outId){
  const a=document.getElementById(idA), b=document.getElementById(idB);
  if(!a||!b) return;
  a.addEventListener('change',()=>{ b.checked=a.checked; recompute(panelId,outId); });
  b.addEventListener('change',()=>{ a.checked=b.checked; recompute(panelId,outId); });
}
syncCheckboxPair('bottleImgSelect','bottleMockupCheck','panel-bottle','subtotalBottle');
syncCheckboxPair('marketingImgSelect','marketingImagesCheck','panel-bottle','subtotalBottle');
document.querySelectorAll('.pricing input[type=checkbox]').forEach(cb=>{
  cb.addEventListener('change',()=>{
    const panel=cb.closest('.panel');
    const outId=panel.id==='panel-front'?'subtotalFront':panel.id==='panel-back'?'subtotalBack':'subtotalBottle';
    recompute(panel.id,outId);
  });
});
recompute('panel-front','subtotalFront');
recompute('panel-back','subtotalBack');
recompute('panel-bottle','subtotalBottle');

// ---------- Preview loader: rising liquid animation, then reveal previews + pricing ----------
function animateLiquidRise(rectEl, duration, onDone){
  const startY=251, endY=80, startH=0, endH=171;
  const t0=performance.now();
  function frame(t){
    const p=Math.min(1,(t-t0)/duration);
    const eased=p<0.5 ? 2*p*p : 1-Math.pow(-2*p+2,2)/2;
    rectEl.setAttribute('y', startY+(endY-startY)*eased);
    rectEl.setAttribute('height', startH+(endH-startH)*eased);
    if(p<1) requestAnimationFrame(frame); else if(onDone) onDone();
  }
  requestAnimationFrame(frame);
}
function wirePreviewLoader(btnId, loaderId, revealId, manual){
  const btn=document.getElementById(btnId);
  const loader=document.getElementById(loaderId);
  const reveal=document.getElementById(revealId);
  const liquidRect=loader.querySelector('.liquid-rect');
  const wineRect=loader.querySelector('.wine-rect');
  let running=false;
  function finish(){
    loader.style.transition='opacity .4s';
    loader.style.opacity='0';
    setTimeout(()=>{
      loader.style.display='none';
      loader.style.transition='';
      loader.style.opacity='1';
      reveal.style.display='block';
      reveal.classList.add('shown');
      running=false;
    },400);
  }
  btn.addEventListener('click',()=>{
    if(running) return;
    running=true;
    btn.style.display='none';
    reveal.classList.remove('shown');
    reveal.style.display='none';
    if(liquidRect){liquidRect.setAttribute('y',251);liquidRect.setAttribute('height',0);}
    if(wineRect){curP=0;targetP=0;wineRect.setAttribute('y',266.6);wineRect.setAttribute('height',0);}
    loader.style.display='flex';
    loader.style.opacity='1';
    if(!manual) animateLiquidRise(liquidRect,2000,finish);
  });
  if(!manual) return;
  /* Manual mode (front): the wine level IS the artwork-generation progress.
     The glass geometry comes from Loader.pdf — full (progress 1) matches the
     PDF's own wine level, about two thirds up the bowl, never the rim. */
  const WINE_BOTTOM=266.6, WINE_RISE=80.9;   // svg units: bowl bottom -> the PDF wine surface
  let curP=0, targetP=0, raf=null;
  function renderWine(){
    curP+=(targetP-curP)*0.10;
    if(Math.abs(targetP-curP)<0.002) curP=targetP;
    const h=Math.max(0,curP)*WINE_RISE;
    wineRect.setAttribute('y',(WINE_BOTTOM-h).toFixed(2));
    wineRect.setAttribute('height',(h+3).toFixed(2));
    raf=(curP!==targetP)?requestAnimationFrame(renderWine):null;
  }
  window.__frontLoaderProgress=function(p){
    if(!running) return;
    targetP=Math.max(targetP,Math.min(1,p||0));
    if(!raf) raf=requestAnimationFrame(renderWine);
  };
  window.__frontLoaderDone=function(){
    if(!running) return;
    targetP=1;curP=1;renderWine();
    finish();
  };
  window.__frontLoaderFail=function(){
    if(!running) return;
    loader.style.display='none';
    btn.style.display='';
    running=false;
  };
}
wirePreviewLoader('frontPreviewBtn','frontLoader','frontReveal', true);
wirePreviewLoader('backPreviewBtn','backLoader','backReveal');
wirePreviewLoader('bottlePreviewBtn','bottleLoader','bottleReveal');


// ---------- Gallery ----------
const galleryCategories = [
  'Traditional / Heritage','Contemporary','Flora & Fauna','Premium','Minimalist','Artistic / Punk','Marketing Images','Our Clients'
];
const styleKeyToCategory = {
  traditional:'Traditional / Heritage', contemporary:'Contemporary', flora:'Flora & Fauna',
  premium:'Premium', minimalist:'Minimalist', artistic:'Artistic / Punk'
};
const galleryItems = [];
const traditionalHeritageSrcs = [
  CLASSIC1_SRC, CLASSIC2_SRC, CLASSIC3_SRC, CLASSIC4_SRC, CLASSIC5_SRC, CLASSIC6_SRC
];
const contemporarySrcs = [
  CONTEMP1_SRC, CONTEMP2_SRC, CONTEMP3_SRC, CONTEMP4_SRC, CONTEMP5_SRC, CONTEMP6_SRC
];
const floraFaunaSrcs = [
  FLORA1_SRC, FLORA2_SRC, FLORA3_SRC, FLORA4_SRC, FLORA5_SRC, FLORA6_SRC
];
const minimalistSrcs = [
  MINIMAL1_SRC, MINIMAL2_SRC, MINIMAL3_SRC, MINIMAL4_SRC, MINIMAL5_SRC, MINIMAL6_SRC
];
const premiumSrcs = [
  PREMIUM1_SRC, PREMIUM2_SRC, PREMIUM3_SRC, PREMIUM4_SRC, PREMIUM5_SRC, PREMIUM6_SRC
];
const artisticPunkSrcs = [
  PUNK1_SRC, PUNK2_SRC, PUNK3_SRC, PUNK4_SRC, PUNK5_SRC, PUNK6_SRC
];
const marketingImagesSrcs = [
  MARKET1_SRC, MARKET2_SRC, MARKET3_SRC, MARKET4_SRC, MARKET5_SRC, MARKET6_SRC, MARKET7_SRC, MARKET8_SRC
];
const categoryImageSets = {
  'Traditional / Heritage': traditionalHeritageSrcs,
  'Contemporary': contemporarySrcs,
  'Flora & Fauna': floraFaunaSrcs,
  'Minimalist': minimalistSrcs,
  'Premium': premiumSrcs,
  'Artistic / Punk': artisticPunkSrcs,
  'Marketing Images': marketingImagesSrcs
};
// "Our Clients" doesn't duplicate any image — it just adds a second tag onto a
// handful of existing items, chosen once at random, so the same photo can
// legitimately appear under both its original category and here.
const ourClientsPicks = [
  {cat:'Marketing Images', src:MARKET2_SRC}, {cat:'Artistic / Punk', src:PUNK6_SRC},
  {cat:'Artistic / Punk', src:PUNK5_SRC}, {cat:'Marketing Images', src:MARKET6_SRC},
  {cat:'Premium', src:PREMIUM4_SRC}, {cat:'Artistic / Punk', src:PUNK4_SRC},
  {cat:'Artistic / Punk', src:PUNK3_SRC}, {cat:'Marketing Images', src:MARKET1_SRC}
];
galleryCategories.forEach(cat=>{
  if(cat==='Our Clients') return; // populated below via tagging, not its own image set
  const srcs = categoryImageSets[cat];
  const count = srcs ? srcs.length : 6;
  for(let i=1;i<=count;i++){
    const item = srcs ? {category:cat, categories:[cat], src:srcs[i-1]} : {category:cat, categories:[cat]};
    const clientPick = ourClientsPicks.find(p=>p.cat===cat && p.src===item.src);
    if(clientPick) item.categories.push('Our Clients');
    galleryItems.push(item);
  }
});

const galleryFiltersEl = document.getElementById('galleryFilters');
const galleryGridEl = document.getElementById('galleryGrid');
let currentGalleryFilter = 'All';

function renderGalleryFilters(){
  const options = ['All', ...galleryCategories];
  galleryFiltersEl.innerHTML = '';
  options.forEach(opt=>{
    const b = document.createElement('button');
    b.className = 'gallery-filter-btn' + (opt===currentGalleryFilter ? ' active' : '');
    b.textContent = opt;
    b.addEventListener('click', ()=>{
      currentGalleryFilter = opt;
      renderGalleryFilters();
      renderGalleryGrid();
    });
    galleryFiltersEl.appendChild(b);
  });
}

function shuffleArray(arr){
  const a = arr.slice();
  for(let i=a.length-1;i>0;i--){
    const j=Math.floor(Math.random()*(i+1));
    [a[i],a[j]]=[a[j],a[i]];
  }
  return a;
}
function renderGalleryGrid(){
  const items = currentGalleryFilter==='All'
    ? shuffleArray(galleryItems)
    : galleryItems.filter(it=>it.categories.includes(currentGalleryFilter));
  currentGalleryItems = items;
  galleryGridEl.innerHTML = '';
  if(items.length===0){
    galleryGridEl.innerHTML = '<div class="gallery-empty">No images yet in this category.</div>';
    return;
  }
  items.forEach((it,i)=>{
    const div = document.createElement('div');
    div.className = 'gallery-item';
    div.style.cursor='pointer';
    const inner = it.src
      ? `<div class="gallery-placeholder"><img src="${it.src}" alt="${it.category}" style="width:100%;height:100%;object-fit:cover;border-radius:4px;"></div>`
      : `<div class="gallery-placeholder">
        <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5"><rect x="3" y="3" width="18" height="18" rx="2"/><circle cx="8.5" cy="8.5" r="1.5"/><path d="M21 15l-5-5L5 21"/></svg>
      </div>`;
    div.innerHTML = `${inner}
      <div class="gallery-caption">${it.category}</div>`;
    div.addEventListener('click', ()=> openLightbox(i));
    galleryGridEl.appendChild(div);
  });
}

// ---------- Gallery lightbox ----------
let currentGalleryItems = [];
let lightboxIndex = 0;
const lightboxOverlay = document.getElementById('lightboxOverlay');
const lightboxCaption = document.getElementById('lightboxCaption');
const lightboxCounter = document.getElementById('lightboxCounter');
const lightboxPlaceholder = document.getElementById('lightboxPlaceholder');

function renderLightbox(){
  const item = currentGalleryItems[lightboxIndex];
  if(!item) return;
  lightboxCaption.textContent = item.category;
  lightboxCounter.textContent = (lightboxIndex+1) + ' / ' + currentGalleryItems.length;
  if(item.src){
    lightboxPlaceholder.innerHTML = `<img src="${item.src}" alt="${item.category}" style="width:100%;height:100%;object-fit:cover;border-radius:4px;">`;
  } else {
    lightboxPlaceholder.innerHTML = `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5"><rect x="3" y="3" width="18" height="18" rx="2"/><circle cx="8.5" cy="8.5" r="1.5"/><path d="M21 15l-5-5L5 21"/></svg>`;
  }
}
function openLightbox(index){
  lightboxIndex = index;
  renderLightbox();
  lightboxOverlay.classList.add('shown');
}
function closeLightbox(){
  lightboxOverlay.classList.remove('shown');
}
function lightboxNext(){
  if(currentGalleryItems.length===0) return;
  lightboxIndex = (lightboxIndex+1) % currentGalleryItems.length;
  renderLightbox();
}
function lightboxPrev(){
  if(currentGalleryItems.length===0) return;
  lightboxIndex = (lightboxIndex-1+currentGalleryItems.length) % currentGalleryItems.length;
  renderLightbox();
}
document.getElementById('lightboxClose').addEventListener('click', closeLightbox);
document.getElementById('lightboxNext').addEventListener('click', lightboxNext);
document.getElementById('lightboxPrev').addEventListener('click', lightboxPrev);
lightboxOverlay.addEventListener('click', (e)=>{
  if(e.target === lightboxOverlay) closeLightbox();
});
document.addEventListener('keydown', (e)=>{
  if(!lightboxOverlay.classList.contains('shown')) return;
  if(e.key === 'Escape') closeLightbox();
  if(e.key === 'ArrowRight') lightboxNext();
  if(e.key === 'ArrowLeft') lightboxPrev();
});

function openGallery(filterKey){
  currentGalleryFilter = filterKey || 'All';
  tabBtns.forEach(b=>b.classList.remove('active'));
  document.querySelectorAll('.panel').forEach(p=>p.classList.remove('active'));
  document.getElementById('panel-gallery').classList.add('active');
  document.getElementById('sharedHero').style.display='none';
  renderGalleryFilters();
  renderGalleryGrid();
  window.scrollTo({top:0, behavior:'smooth'});
  checkCoverOverlap();
}

const topnavLinks = document.querySelectorAll('.topnav a');
if(topnavLinks[1]){
  topnavLinks[1].addEventListener('click', (e)=>{
    e.preventDefault();
    openGallery('All');
  });
}

