// ---------- Live chat ----------
const chatFab = document.getElementById('chatFab');
const chatPanel = document.getElementById('chatPanel');
const chatClose = document.getElementById('chatClose');
const chatMessages = document.getElementById('chatMessages');
const chatInput = document.getElementById('chatInput');
const chatSend = document.getElementById('chatSend');

function toggleChat(){
  const opening = !chatPanel.classList.contains('shown');
  chatPanel.classList.toggle('shown', opening);
  chatFab.classList.toggle('open', opening);
}
function closeChat(){
  chatPanel.classList.remove('shown');
  chatFab.classList.remove('open');
}
chatFab.addEventListener('click', toggleChat);
chatClose.addEventListener('click', closeChat);

const canned = [
  "Thanks for reaching out! A member of our team will be with you shortly.",
  "Great question — while you wait, feel free to keep exploring the Front Label, Back Label, and Bottle & Marketing tabs.",
  "Got it! We'll follow up by email if we need anything else from you."
];
let cannedIndex = 0;

function addChatMessage(text, from){
  const msg = document.createElement('div');
  msg.className = 'chat-msg ' + (from==='user' ? 'chat-msg-user' : 'chat-msg-bot');
  msg.textContent = text;
  chatMessages.appendChild(msg);
  chatMessages.scrollTop = chatMessages.scrollHeight;
}
function sendChatMessage(){
  const text = chatInput.value.trim();
  if(!text) return;
  addChatMessage(text, 'user');
  chatInput.value = '';
  setTimeout(()=>{
    addChatMessage(canned[cannedIndex % canned.length], 'bot');
    cannedIndex++;
  }, 700);
}
chatSend.addEventListener('click', sendChatMessage);
chatInput.addEventListener('keydown', (e)=>{
  if(e.key === 'Enter') sendChatMessage();
});
